import json,pathlib
root=pathlib.Path('/workspace/sites/olympiad-atlas'); path=root/'data/americas.json'; bank=[x for x in json.load(open(path)) if x['country'] in ['Canada','United States']]; rows=[]
def add(country,comp,y,n,d,topic,tags,statement,solution,reason,url,solurl=None):
 rows.append(dict(id=f'{country.lower()}-{comp.lower().replace(" ","-")}-{y}-{n}',country=country,competition=comp,year=y,number=str(n),difficulty=d,topic=topic,tags=tags,statement=statement,solution=solution,solutionKind='source-link' if solurl else 'original-exposition',sourceUrl=url,solutionUrl=solurl or url,ratingReason=reason,reviewStatus='individually-assessed',notes='English mathematical paraphrase of the official Spanish or Portuguese statement. Individual assessment based on the actual proof.'))
def omm(y):return f'https://www.ommenlinea.org/wp-content/uploads/concursos/nacionales/nac{y-1986}.pdf'
def state(y):return f'https://www.ommenlinea.org/wp-content/uploads/practica/finales/final{str(y)[2:]}.pdf'
def statesol(y):return f'https://www.ommenlinea.org/wp-content/uploads/practica/finales/solfinal{str(y)[2:]}.pdf'
def sadd(y,n,d,t,tags,s,r):
 u=statesol(y);add('Mexico','OMM State Final',y,n,d,t,tags,s,f'[View the official worked solutions in Spanish (PDF)]({u}). Find Problem {n}.',r,state(y),u)
sadd(2013,2,4,'Number Theory',['primes','divisibility'],r'Find all triples of positive primes $(p,q,r)$ satisfying $2pq=7rq+5q+3p$.','Rearrange to make q divide 3p, split into q=3 and q=p, and then use parity. The small but necessary case split distinguishes this from a one-step divisibility exercise.')
sadd(2013,5,4.5,'Combinatorics',['pigeonhole principle','modular arithmetic','construction'],r'Find the least integer $n\ge3$ such that every partition of $\{1,2,\ldots,n\}$ into three sets has one set containing three distinct elements whose sum is divisible by $3$.','A five-element residue argument supplies the threshold. To prove minimality, one must distribute residues into three four-element sets without either three equal residues or all three residues.')
sadd(2013,7,4.5,'Geometry',['similarity','circle angles'],r'In triangle $ABC$, $AB=AC$ and $\angle A=90^\circ$. Choose $D\in BC$ with $BD=2DC$, and let $E$ be the perpendicular projection of $B$ onto $AD$. Determine $\angle CED$.','A coordinate solution is feasible, but controlling the projection and recovering the exact angle takes several steps. A synthetic solution adds a circle intersection and uses the 2:1 ratio twice.')
sadd(2014,2,4,'Geometry',['reflection','orthocentre','concurrency'],r'In an acute triangle $ABC$, let $D,E,F$ be the feet of the altitudes from $A,B,C$. Choose $D^{\prime}\in BC$, $E^{\prime}\in CA$, $F^{\prime}\in AB$ such that $BD=D^{\prime}C$, $CE=E^{\prime}A$, and $AF=F^{\prime}B$. Prove that the perpendiculars to $BC,CA,AB$ at $D^{\prime},E^{\prime},F^{\prime}$ concur.','A half-turn about the circumcentre takes each altitude line to the corresponding new perpendicular. Identifying this global transformation supplies a compact concurrency proof.')
sadd(2014,5,4.5,'Number Theory',['modular arithmetic','periodicity'],r'Label the vertices of a regular $160$-gon $1,\ldots,160$ clockwise. Mark a chosen starting vertex. From an even label $v$, move $v$ steps clockwise; from an odd label $v$, move $v$ steps anticlockwise. Mark each reached vertex and stop at the first repeated vertex. What is the greatest possible number of marked vertices?','Odd starts collapse immediately; even starts follow doubling modulo 160. One must bound all tails and cycles and exhibit a start attaining eight distinct vertices.')
sadd(2014,6,5,'Geometry',['cyclic quadrilaterals','symmetry','circle angles'],r'A cyclic quadrilateral $ABCD$ has $AD\parallel BC$, $AD<BC$, and circumcentre $O$ outside the quadrilateral. Put $E=AB\cap CD$. Let $F$ be the foot of the perpendicular from $E$ to $BO$, and put $G=EF\cap BC$. Prove that $A,G,O,C,E$ are concyclic.','Use the axis of symmetry of the isosceles trapezium to establish two overlapping cyclic quadrilaterals. Several complementary angles must be matched, but no advanced theorem is required.')
sadd(2015,2,4,'Geometry',['angle chasing','regular polygons'],r'Let $ABCDE$ be a regular pentagon and construct the equilateral triangle $AFE$ outside it. A point $P$ on $BF$, inside the pentagon, satisfies $\angle AEP=12^\circ$. Find $\angle CAP$.','The 108° and 60° angles create two successive isosceles triangles. Recognizing the resulting equal lengths unlocks the final 12° angle.')
sadd(2015,4,5.5,'Combinatorics',['geometry','extremal','construction'],r'Call a segment joining two sides of an equilateral triangle and parallel to the third side a chord. Find the least $n$ for which one can draw $n$ such chords parallel to each side and obtain exactly $180$ distinct intersection points.','The upper bound 3n² gives only the minimum candidate. A careful arrangement must realize exactly 180 points, avoiding triple intersections and adjusting one chord to create precisely four final crossings.')
sadd(2015,6,6,'Geometry',['reflection','similarity','angle bisectors'],r'Fold rectangle $ABCD$ along $EF$, where $E\in AB$ and $F\in CD$, sending $B$ to $B^{\prime}\in AD$ and $C$ to $C^{\prime}$. Let $G=B^{\prime}C^{\prime}\cap CD$, and let $H$ be the perpendicular projection of $G$ onto $EF$. The bisector of $\angle AEB^{\prime}$ meets $AD$ at $I$. Prove $GH/CF=EB/EI$.','The fold gives equal lengths and angles, but the ratio needs an auxiliary cyclic quadrilateral followed by a non-obvious pair of similar triangles. The angle-bisector condition matters near the end.')
add('Mexico','OMM National',2014,1,4,'Combinatorics',['graphs','invariants','operations'],r'Each integer from $1$ to $4027$ is coloured red or green. In one move, choose two integers whose ratio, in one order, is prime and switch both colours. Prove that a sequence of moves can make every integer from $1$ to $2014$ green.',r'Join two numbers when their ratio is prime. This graph is connected: repeatedly dividing a number by a prime factor gives a path to $1$. If two vertices are the endpoints of a path, switching the edges of the path in order changes exactly those endpoints, since every internal vertex is switched twice. Fix vertex $4027$. For each red vertex among $1,\ldots,2014$, apply such a path from it to $4027$. This changes that vertex to green and leaves every other vertex in the target range unchanged. After finitely many paths all target vertices are green.','The useful reformulation is a connected graph. A path toggles only its endpoints, so one spare vertex absorbs all colour changes. The proof requires inventing that operation.',omm(2014))
add('Mexico','OMM National',2014,2,5.5,'Number Theory',['digits','divisibility','classification'],r'A positive integer $a$ can be reduced to $b$ when division by the units digit of $a$ gives the positive integer $b$. Find every positive integer that can reach $1$ after finitely many reductions.',r'Work backwards. If $b$ is followed backwards by $a=db$, where $1\le d\le9$, then the last digit of $a$ must be $d$. Thus the necessary and sufficient condition is $d(b-1)\equiv0\pmod{10}$. Ignore $d=1$, which makes no progress. Starting at $1$ gives the digits $1,\ldots,9$. From a number ending in $3,5,7,$ or $9$, the only further multiplier is $5$, after which the last digit is $5$. From a number ending in $6$, the possible multipliers are $2,4,6,8$; only multiplier $6$ permits further growth. Numbers ending in $2,4,$ or $8$ have no further predecessor. There is no new number ending in $1$. Consequently the answer is $1$, all $u5^k$ with $u\in\{1,3,7,9\}$ and $k\ge0$, and all $v6^k$ with $v\in\{2,4,6,8\}$ and $k\ge0$. Each listed number is reached by the described backwards construction.','Reverse the process and turn the final-digit rule into a congruence. Classifying the possible last digits reveals two infinite families and requires proving completeness as well as reachability.',omm(2014))
add('Mexico','OMM National',2014,5,5,'Algebra',['Cauchy-Schwarz','AM-GM','inequalities'],r'For positive reals $a+b+c=3$, prove $\frac{a^2}{a+\sqrt[3]{bc}}+\frac{b^2}{b+\sqrt[3]{ca}}+\frac{c^2}{c+\sqrt[3]{ab}}\ge\frac32$, and determine equality.',r'AM–GM gives $3\sqrt[3]{bc}\le b+c+1$. Adding the three cyclic versions yields $\sqrt[3]{bc}+\sqrt[3]{ca}+\sqrt[3]{ab}\le3$. By Cauchy–Schwarz, the required sum is at least $(a+b+c)^2/(a+b+c+\sqrt[3]{bc}+\sqrt[3]{ca}+\sqrt[3]{ab})\ge9/6=3/2$. Equality in all three AM–GM inequalities requires $a=b=c=1$, which also gives equality in the original expression.','Cauchy–Schwarz reduces the rational expression to a sum of cube roots. Adding a constant 1 to each AM–GM triple is the useful normalization, and equality must be tracked.',omm(2014))
add('Mexico','OMM National',2015,2,4.5,'Combinatorics',['bijections','binomial coefficients'],r'In an $n\times n$ grid, choose $k$ rectangles with integer side lengths, grid-parallel sides, and the same upper-right corner as the grid, where $1\le k\le n$. Colour their union black. How many different remaining white shapes require exactly $k$ rectangles, meaning they cannot arise from fewer?',r'Remove every rectangle contained in another. In an irredundant collection, the widths are distinct and, when listed increasingly, the heights are strictly decreasing; otherwise one rectangle contains another. Conversely, any increasing choice of $k$ widths and decreasing choice of $k$ heights gives an irredundant staircase with exactly $k$ exposed corners. The boundary recovers all its widths and heights, so different choices give different shapes. There are $\binom nk$ choices for each list, giving $\boxed{\binom nk^2}$.','The challenge is recognizing that redundant rectangles correspond to containment. Once the exposed staircase corners are identified, two independent subset choices give the exact count.',omm(2015))
add('Mexico','OMM National',2015,6,6.5,'Number Theory',['divisor sums','prime factorisation'],r'Define $F(n)=\sum_{d\mid n}(-1)^d d$, summing over positive divisors. If $F(n)$ is a power of $2$, prove that $n$ is squarefree.',r'Write $n=2^a m$ with $m$ odd. Then $F(n)=(2^{a+1}-3)\sigma(m)$, where $\sigma$ is the sum of divisors. Since $F(n)>0$, $a\ge1$. Its odd factor $2^{a+1}-3$ must be $1$, so $a=1$. For each odd prime power $p^e\mid m$, the factor $1+p+\cdots+p^e$ must be a power of $2$. If $e+1$ has an odd divisor $q>1$, then this sum has the odd factor $1+p^r+\cdots+p^{(q-1)r}>1$, where $r=(e+1)/q$, impossible. Thus $e+1$ is a power of $2$. If $e+1\ge4$, the divisor sum has factor $p^2+1$. But $p^2+1\equiv2\pmod8$ and is greater than $2$, so it has an odd prime factor. Therefore $e=1$ for every odd prime, proving squarefreeness.','Separate the power of 2 and factor the divisor sum. The final obstruction uses both the exponent e+1 and the fact that an odd square is 1 modulo 8; this is a substantial multi-step classification.',omm(2015))
add('Mexico','OMM National',2016,3,4,'Algebra',['floor function','sequences','inequalities'],r'Find the least real $x$ for which $\lfloor x\rfloor<\lfloor x^2\rfloor<\lfloor x^3\rfloor<\cdots$ holds indefinitely.',r'Necessarily $x>1$: values in $[0,1]$ cannot work, and for $x<0$ the second and third powers violate the order. Hence $\lfloor x^3\rfloor\ge3$, giving $x\ge\sqrt[3]3$. Put $x=\sqrt[3]3$. Its first three floors are $1,2,3$. Also $x>4/3$, so for every $n\ge3$, $x^{n+1}-x^n=x^n(x-1)\ge3(x-1)>1$. Every subsequent floor therefore strictly increases. The minimum is $\boxed{\sqrt[3]3}$.','Early floor inequalities suggest the candidate, but checking infinitely many later terms requires bounding the gaps between consecutive powers. Domain cases must also be excluded.',omm(2016))
add('Mexico','OMM National',2016,4,5.5,'Number Theory',['digits','pigeonhole principle','modular arithmetic'],r'Find the greatest nonnegative integer whose decimal representation has no consecutive block of digits representing a multiple of $7$. A single digit is allowed as a block, and $0$ counts as a multiple of $7$.',r'No such number has seven or more digits. For its first seven digits, let $P_i$ be the prefix of length $i$, with $P_0=0$. The eight residues $10^{-i}P_i\pmod7$ include a repeated pair. If $i<j$ have the same residue, then $P_j-10^{j-i}P_i$ is divisible by $7$, yielding a forbidden block. Now $999993$ works: its blocks are strings of 9s of length at most five, or a string of 9s followed by 3. Their residues are respectively $2,1,5,3,4$ and $3,2,6,4,5,1$, all nonzero. The six larger six-digit candidates fail: $999994$ contains $994$, $999995$ contains $99995$, $999996$ contains $9996$, $999997$ contains $7$, $999998$ contains $98$, and $999999$ is itself divisible by $7$. Thus the answer is $999993$.','Normalized prefix residues supply the non-obvious length bound. A short but exact final check proves which six-digit candidate is greatest.',omm(2016))
add('Mexico','OMM National',2017,2,6,'Number Theory',['least common multiple','extremal','subsets'],r'A finite set of $n$ distinct positive integers is balanced if the average of every $k$-element subset is an integer for each $1\le k\le n$. Find the greatest possible sum of a balanced set whose elements are all at most $2017$.',r'For any $k<n$, compare two $k$-element subsets differing in only one element. Their sums are divisible by $k$, so every pair of elements is congruent modulo $k$. If $n\ge8$, the elements are all congruent modulo $\operatorname{lcm}(1,\ldots,7)=420$; eight distinct such positive integers span at least $2940$, impossible. If $n\le6$, the sum is at most $6\cdot2017=12102$. If $n=7$, all elements are congruent modulo $60$, so their sum is at most $7\cdot2017-60(0+1+\cdots+6)=12859$. The set $\{1657,1717,1777,1837,1897,1957,2017\}$ attains this: for $k\le6$, its subset averages are integers because $k\mid60$, and its seven-element average is $1837$. Therefore the maximum is $12859$.','Comparing overlapping subsets reveals a strong common modulus. The argument then changes from congruences to a sharp size bound and an extremal arithmetic progression.',omm(2017))
add('Mexico','OMM National',2017,4,4,'Combinatorics',['triangle inequality','extremal'],r'Find the greatest size of a subset $B\subseteq\{1,2,\ldots,2017\}$ such that every three distinct members are the side lengths of a nondegenerate triangle.',r'Write the elements as $b_1<\cdots<b_k$. The condition requires $b_1+b_2>b_k$. Since $b_k\ge b_2+k-2$, we get $b_1\ge k-1$, and then $b_k\ge b_1+k-1\ge2k-2$. As $b_k\le2017$, this gives $k\le1009$. The $1009$ integers $1009,1010,\ldots,2017$ work: the sum of the smallest two is $2019$, greater than the largest. Thus the answer is $1009$.','Only the two smallest and the largest matter, but distinctness must be converted into a sharp bound on the span. A consecutive interval realizes equality.',omm(2017))
obm={(2021,2):'https://www.obm.org.br/content/uploads/2022/02/obm2021_nivel2.pdf',(2022,2):'https://www.obm.org.br/content/uploads/2022/11/obm2022_nivel2.pdf',(2023,2):'https://www.obm.org.br/content/uploads/2023/10/Nivel_2_OBM_2023.pdf',(2023,3):'https://www.obm.org.br/content/uploads/2023/10/Nivel_3_OBM_2023.pdf',(2024,2):'https://www.obm.org.br/content/uploads/2024/10/OBM2024_N2.pdf',(2024,3):'https://www.obm.org.br/content/uploads/2024/10/OBM2024_N3.pdf'}
def badd(y,l,n,d,t,tags,s,sol,r):add('Brazil',f'OBM Level {l}',y,n,d,t,tags,s,sol,r,obm[y,l])
badd(2021,2,5,6,'Number Theory',['divisibility','Egyptian fractions','case analysis'],r'Find all triples of positive integers $(a,b,c)$ such that $a\mid bc+1$, $b\mid ca+1$, and $c\mid ab+1$.',r'The conditions are symmetric, so assume $a\le b\le c$. Every pair is coprime: a common divisor of $a,b$ would divide $bc+1$ and $bc$. If $a=1$, then $c\mid b+1$, so either $b=c=1$, or $c=b+1$. In the latter case $b\mid c+1=b+2$, giving $(1,1,2)$ or $(1,2,3)$. Now suppose $a\ge2$. Pairwise coprimality implies $abc\mid ab+bc+ca+1$, so $K=1/a+1/b+1/c+1/(abc)$ is a positive integer. If $a\ge3$, coprimality forces $b\ge4,c\ge5$, giving $K<1$, impossible. Thus $a=2$ and $b\ge3,c\ge5$; here $K<2$, hence $K=1$. This becomes $(b-2)(c-2)=5$, giving $(2,3,7)$. All four triples work, so the answer consists of their permutations.','Combining pairwise coprimality with a symmetric divisibility condition creates an integer reciprocal sum. Ordering the variables then reduces the classification to a few sharply bounded cases.')
badd(2021,2,6,5.5,'Number Theory',['floor function','density','sequences'],r'For $\alpha\ge1$, let $A(\alpha)=\{\lfloor n\alpha\rfloor:n=1,2,\ldots\}$. Suppose the positive integers outside $A(\alpha)$ are exactly one residue class modulo $2021$. Find all possible $\alpha$.',r'The sequence $\lfloor n\alpha\rfloor$ is strictly increasing. Its number of terms at most $N$ is $N/\alpha+O(1)$, since $\lfloor n\alpha\rfloor\le N$ is equivalent to $n\alpha<N+1$. The hypothesis gives instead $2020N/2021+O(1)$. Dividing by $N$ and letting $N$ grow yields $\alpha=2021/2020$. This value works: write $n=2020q+r$ with $0\le r<2020$. Then $\lfloor n\alpha\rfloor=2021q+r$. As $n$ ranges over positive integers, these are exactly the positive integers whose residues modulo $2021$ are $0,1,\ldots,2019$. Thus the omitted residue is $2020$, and the unique value is $2021/2020$.','Count how quickly the floor sequence fills the integers to force a unique parameter, then verify the exact missing residue. The density argument is the conceptual step; it can also be written with elementary counting bounds.')
badd(2023,2,3,6.5,'Number Theory',['systems of equations','factorisation','construction'],r'Prove that there exist integers $x_1,\ldots,x_n$, not all equal, satisfying $x_i^2+\sum_{j\ne i}x_j=0$ for every $i$, if and only if $2n-1$ is composite.',r'Put $S=\sum x_i$. Every $x_i$ is a root of $X^2-X+S=0$. As they are not all equal, both integer roots $a,1-a$ occur. Let $k$ copies equal $a$, and put $u=2a-1$, $v=2k-n$. Comparing the sum with $S=a-a^2$ gives $u(u+2v)=-(2n-1)$, with $|v|\le n-2$. If $2n-1$ is prime, its only factorizations force $|v|=n$, a contradiction; if $n=1$, the requirement “not all equal” is impossible. Conversely, write $2n-1=pq$ with odd $p,q\ge3$. Take $u=p$, $v=-(p+q)/2$, $a=(p+1)/2$, and $k=(n+v)/2$. The congruence $p+q\equiv pq+1\pmod4$ ensures that $k$ is integral. Also $p+q\le pq-3=2n-4$, so $1\le k\le n-1$. Taking $k$ copies of $a$ and $n-k$ copies of $1-a$ satisfies the equations by reversing the calculation.','The equations force exactly two possible coordinate values. Turning their multiplicities into a factorization of 2n−1, and then rebuilding a valid tuple from any factorization, requires several coordinated steps.')
badd(2023,2,4,4.5,'Number Theory',['perfect squares','inequalities','extremal'],r'Find the least integer $k$ for which pairwise distinct positive integers $a,b,c$ satisfy $a^2=bc$ and $k=2b+3c-a$.',r'Write $b=tr^2$, $c=ts^2$, $a=trs$, where $t,r,s$ are positive integers and $r\ne s$. This follows by factoring out $\gcd(b,c)$: the remaining coprime factors have square product, so each is a square. Then $k=t(2r^2+3s^2-rs)\ge t(\tfrac32r^2+\tfrac52s^2)$. If $r\ge2$, the right side is at least $8.5$, so the integral $k$ is at least $9$. If $r=1$, then $s\ge2$, giving $k\ge12$. The choice $(a,b,c)=(2,4,1)$ gives $k=9$, so the minimum is $9$.','Parametrizing two integers with square product reveals a small positive quadratic form. A simple bound and the distinctness condition reduce the minimization to one explicit example.')
badd(2023,2,5,6,'Number Theory',['Chinese remainder theorem','Euler theorem','congruences'],r'Call an integer $n\ge3$ fabulous if some integer $a$ with $2\le a\le n-1$ satisfies $n\mid a^n-a$. Determine all fabulous integers.',r'Every odd $n\ge3$ works with $a=n-1$, since $(-1)^n=-1$. If $n$ is even but not a power of $2$, write $n=2^s m$, where $m>1$ is odd. The Chinese remainder theorem gives $a\equiv0\pmod m$ and $a\equiv1\pmod{2^s}$, with $0\le a<n$. This $a$ is neither $0$ nor $1$, and $a^n\equiv a$ modulo both coprime factors, hence modulo $n$. Finally, let $n=2^s\ge4$. If $a$ is even, $a^n\equiv0\pmod n$, so the condition would force $a\equiv0$. If $a$ is odd, Euler’s theorem gives $a^n\equiv1\pmod n$, forcing $a\equiv1$. Both contradict the required range. Thus precisely the integers $n\ge3$ that are not powers of $2$ are fabulous.','Odd n has a simple witness, but the even case needs a CRT construction. Excluding all powers of 2 requires a separate argument using parity and Euler’s theorem.')
badd(2023,3,1,5.5,'Number Theory',['multiplicative functions','construction','prime valuations'],r'Construct an infinite sequence of nonzero integers $a_1,a_2,\ldots$ such that $a_n+a_{2n}+\cdots+a_{2023n}=0$ for every positive integer $n$.',r'The number $2017$ is prime (trial division by primes at most $43$ verifies this), and its only multiple in $1,\ldots,2023$ is itself. Let $v_{2017}(m)$ be its exponent in $m$, and define $a_m=(-2022)^{v_{2017}(m)}$. These are nonzero integers and $a_{mn}=a_ma_n$. Among $a_1,\ldots,a_{2023}$, exactly one term is $-2022$ and the other $2022$ terms are $1$, so their sum is zero. Consequently $\sum_{j=1}^{2023}a_{jn}=a_n\sum_{j=1}^{2023}a_j=0$ for every $n$, as required.','An infinite family of linked constraints becomes one finite sum if the sequence is completely multiplicative. Choosing a prime near 2023 makes that finite sum easy to control.')
badd(2023,3,4,4.5,'Algebra',['systems of equations','symmetric expressions','inequalities'],r'Distinct real numbers $x,y,z$ satisfy $x^2-x=yz$, $y^2-y=zx$, and $z^2-z=xy$. Prove that each lies strictly between $-1/3$ and $1$.',r'Subtracting the first two equations gives $(x-y)(x+y+z-1)=0$. Distinctness forces $x+y+z=1$. The first equation now gives $xy+xz+yz=0$, hence $x^2+y^2+z^2=1$. Since $y\ne z$, $(y+z)^2<2(y^2+z^2)$. Substituting gives $(1-x)^2<2(1-x^2)$, or $(3x+1)(x-1)<0$. Thus $-1/3<x<1$, and the other bounds follow cyclically.','Subtract the equations to expose the sum of the variables, then use a strict two-variable square inequality. Distinctness is essential both for the algebraic reduction and for strict endpoints.')
badd(2024,2,4,4,'Combinatorics',['digits','divisibility','counting'],r'How many ten-digit positive integers use only the digits $1,2,3$ and are divisible by $99$?',r'Divisibility by $11$ requires the sums in the five odd and five even positions to be equal: their difference lies between $-10$ and $10$, so its only multiple of $11$ is zero. The total digit sum is an even multiple of $9$ between $10$ and $30$, hence it is $18$. Each group of five digits therefore sums to $9$. Subtract $1$ from each digit in one group: five entries in $\{0,1,2\}$ must sum to $4$. Without the upper bound there are $\binom84=70$ choices; exactly $5\binom54=25$ have an entry at least $3$, and two such entries are impossible. Thus each group has $45$ choices, independently, giving $45^2=2025$.','Combine the two divisibility rules to fix both alternating digit sums, then count bounded compositions. The short inclusion–exclusion step is the main counting hurdle.')
badd(2024,3,2,5.5,'Combinatorics',['bijections','set partitions'],r'Prove that the number of set partitions of $\{1,\ldots,n\}$ equals the number of set partitions of $\{1,\ldots,n+1\}$ in which no block contains consecutive integers.',r'Represent a partition by drawing a directed edge from each element of a block to the next larger element in that block. Every vertex has at most one incoming and one outgoing edge, and all edges point to larger labels. Replace every edge $(a,b)$ by $(a,b+1)$. On vertices $1,\ldots,n+1$, these edges still form disjoint increasing paths, so they define another partition; every edge has length at least $2$, so no block contains consecutive labels. Conversely, in such a partition every edge $(a,b)$ has $b\ge a+2$. Replace it by $(a,b-1)$. The resulting edges are increasing paths on $1,\ldots,n$ and define a partition there. The two operations undo each other, providing the desired bijection.','The counting relation becomes transparent only after encoding blocks as paths and shifting edge endpoints. Verifying that the map and its inverse preserve partitions is the central insight.')
oma='https://oma.org.ar/enunciados/NACIONAL_OMA_2024.pdf'
def aadd(l,n,d,t,tags,s,sol,r):add('Argentina',f'OMA National Level {l}',2024,n,d,t,tags,s,sol,r,oma)
aadd(2,3,4,'Number Theory',['prime valuations','arithmetic progressions','construction'],r'(a) Give an infinite arithmetic progression of positive integers containing no perfect $k$th power for any integer $k\ge2$. (b) Give one containing no square but infinitely many cubes.',r'(a) Take $2,6,10,14,\ldots$, the numbers $2+4n$. Each has exactly one factor of $2$, whereas the exponent of every prime in a perfect $k$th power is divisible by $k$. (b) Take $8,24,40,56,\ldots$, the numbers $8+16n$. Each has exactly three factors of $2$, so none is a square. For every positive odd integer $t$, the cube $(2t)^3=8t^3$ is $8$ modulo $16$, so infinitely many cubes belong to the progression.','The shared idea is to fix an exact prime exponent throughout a progression. Choosing exponent 1 rules out every higher power; exponent 3 permits cubes while excluding squares.')
aadd(2,5,4,'Combinatorics',['invariants','modular arithmetic','construction'],r'Three ants begin at one vertex of a regular $n$-gon, $n\ge3$. Each minute, two ants move to neighbouring vertices in opposite directions, while the third stays still. For which $n$ can all three eventually meet at a different vertex?',r'Label vertices by residues modulo $n$, starting at $0$. The sum of the three labels is invariant modulo $n$. If they meet at $j\ne0$, then $3j\equiv0\pmod n$, which is possible only when $3\mid n$. Conversely, write $n=3r$. Move the first ant clockwise and the third anticlockwise for $r$ moves; then move the second clockwise and the third anticlockwise for another $r$ moves. Their displacements are $(r,r,-2r)$, all congruent to $r$ modulo $n$. Thus exactly the multiples of $3$ work.','A modular sum gives the obstruction, but a complete solution must also realize the allowed meeting vertex with an explicit sequence of paired moves.')
aadd(3,1,4.5,'Algebra',['systems of equations','factorisation'],r'Find all real quadruples satisfying $ab+c+d=6$, $bc+d+a=2$, $cd+a+b=5$, and $da+b+c=3$.',r'Adding the first and third equations and subtracting the other two yields $(a-c)(b-d)=6$, so $b\ne d$. Subtract the third equation from the first and the fourth from the second, then add: $(b-d)(a+c-2)=0$. Hence $a+c=2$. Adding all four equations gives $(a+c)(b+d)+2(a+b+c+d)=16$, so $b+d=3$. Set $u=a-1$ and substitute $c=2-a$, $d=3-b$ into the first equation to obtain $ub=u+2$. Meanwhile $(a-c)(b-d)=6$ gives $u(2b-3)=3$. These imply $u=1$ and $b=3$. Thus $(a,b,c,d)=(2,3,0,0)$, which satisfies all four equations.','Opposite differences and sums factor into useful products. The problem needs a deliberate elimination order and attention to possible zero factors, then a short linear finish.')
aadd(3,5,4.5,'Geometry',['coordinates','ratios','AM-GM'],r'Choose $A^{\prime}\in BC$, $B^{\prime}\in CA$, $C^{\prime}\in AB$ in triangle $ABC$ such that $BA^{\prime}/A^{\prime}C=CB^{\prime}/B^{\prime}A=AC^{\prime}/C^{\prime}B$. The line through $A^{\prime}$ parallel to $B^{\prime}C^{\prime}$ meets lines $AC,AB$ at $P,Q$. Prove $PQ/B^{\prime}C^{\prime}\ge2$.',r'Write the common positive ratio as $t$, and use vectors with $A=0$, $B=u$, $C=v$. Then $A^{\prime}=(u+tv)/(1+t)$, $B^{\prime}=v/(1+t)$, $C^{\prime}=tu/(1+t)$. The line through $A^{\prime}$ parallel to $B^{\prime}C^{\prime}$ consists of $(u+tv+s(tu-v))/(1+t)$. Setting its $v$ coefficient to zero gives $Q=(1+t^2)u/(1+t)$; setting its $u$ coefficient to zero gives $P=(t+t^{-1})v/(1+t)$. Therefore $Q-P=(t+t^{-1})(C^{\prime}-B^{\prime})$, so $PQ/B^{\prime}C^{\prime}=t+t^{-1}\ge2$ by AM–GM, with equality when $t=1$.','Encode the cyclic ratios with one parameter and use parallelism to find the two intercepts. The geometric ratio simplifies to t+1/t, giving a clean inequality after moderate coordinate algebra.')
